  KEY `data_import_rows_batch_id_validation_status_index` (`batch_id`,`validation_status`),
  KEY `data_import_rows_batch_id_processing_status_index` (`batch_id`,`processing_status`),
  KEY `data_import_rows_batch_id_identifier_index` (`batch_id`,`identifier`),
  CONSTRAINT `data_import_rows_batch_id_foreign` FOREIGN KEY (`batch_id`) REFERENCES `data_import_batches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
